  WITH (fillfactor = 70, autovacuum_enabled = off);
INSERT INTO accounts SELECT g, 100000 FROM generate_series(1, 20000) g;
SELECT ctid FROM accounts WHERE id IN (42, 17042);
CHECKPOINT;
SELECT count(*) FILTER (WHERE isdirty) AS dirty_pages
FROM pg_buffercache WHERE relfilenode = pg_relation_filenode('accounts');

BEGIN;
UPDATE accounts SET balance_cents = balance_cents - 2500 WHERE id = 42;
UPDATE accounts SET balance_cents = balance_cents + 2500 WHERE id = 17042;
COMMIT;

SELECT relblocknumber, isdirty FROM pg_buffercache
WHERE relfilenode = pg_relation_filenode('accounts') AND isdirty ORDER BY 1;
SELECT lsn AS in_memory FROM page_header(get_raw_page('accounts', 0));
SELECT pg_relation_filepath('accounts') AS f \gset
\setenv F :f
\! od -A n -t x4 -N 8 /var/lib/postgresql/18/docker/$F
CHECKPOINT;
\! od -A n -t x4 -N 8 /var/lib/postgresql/18/docker/$F

VACUUM accounts;
SELECT pg_current_wal_insert_lsn() AS before \gset
BEGIN;
UPDATE accounts SET balance_cents = balance_cents - 1000 WHERE id = 42;
UPDATE accounts SET balance_cents = balance_cents + 1000 WHERE id = 17042;
COMMIT;
SELECT pg_current_wal_insert_lsn() AS after \gset
SELECT pg_wal_lsn_diff(:'after', :'before') AS wal_bytes;
\setenv B :before
\setenv E :after
\! pg_waldump -p /var/lib/postgresql/18/docker/pg_wal -s $B -e $E

SELECT 0 AS blk, lsn FROM page_header(get_raw_page('accounts', 0))
UNION ALL SELECT 132, lsn FROM page_header(get_raw_page('accounts', 132));
SELECT pg_current_wal_flush_lsn() AS flushed;

CREATE TABLE wallets (id int PRIMARY KEY, balance_cents bigint)
  WITH (fillfactor = 90, autovacuum_enabled = off);
INSERT INTO wallets SELECT g, 100000 FROM generate_series(1, 20000) g;
SELECT count(*) FROM wallets;
SELECT pg_relation_size('wallets') / 8192 AS pages;

CHECKPOINT;
