private fun recover() {
    val checkpoint = control.read()?.let { wal.readAt(it) }
    val start = checkpoint?.value ?: 0L                   // redo LSN, or the start of the log
    val records = wal.recover(start)                      // stops at the torn tail and truncates it
    val pending = HashMap<Int, LinkedHashMap<Int, Long>>()
    var redone = 0
    for (r in records) {
        when (r.type) {
            RecordType.BEGIN -> pending[r.txId] = LinkedHashMap()
            RecordType.UPDATE -> pending.getOrPut(r.txId) { LinkedHashMap() }[r.pageId] = r.value
            RecordType.COMMIT -> for ((id, v) in pending.remove(r.txId).orEmpty()) {
                val p = page(id)
                if (p.lsn < r.endLsn) {                   // the page doesn't have this commit yet
                    p.value = v; p.lsn = r.endLsn; p.dirty = true; redone++
                }
            }
            RecordType.ABORT -> pending.remove(r.txId)
            RecordType.CHECKPOINT -> {}
        }
    }
    lastRecovery = RecoveryStats(records.size, redone)  // what is left in pending never committed
}

// The page LSN check: a change is applied only to a page whose LSN is older than the commit,
// and applying it sets the LSN, so a second run skips everything the first one did.
